/**
 * html.ts
 * Regex-based extraction over built HTML — deliberately not a real DOM parser.
 * dist/ output is machine-generated by Astro, so its shape is stable enough
 * that this holds; a real DOM parser would be justified the moment these
 * scripts need to handle hand-authored or third-party HTML, which they don't.
 *
 * Every function here was previously duplicated, with small inconsistent
 * variations, across seo-regression.mjs, link-integrity.mjs, asset-inventory.mjs,
 * budget-gate.mjs, check-csp-contract.mjs and check-url-contract.mjs.
 *
 * Capture-group note: every regex below has a fixed, mandatory number of
 * capture groups (no optional groups, no alternation inside a group), so a
 * successful match always populates every group — TypeScript's
 * `RegExpMatchArray` type just can't express that, which is what
 * `noUncheckedIndexedAccess` is (correctly) flagging. The `?? ''` fallbacks
 * below exist to satisfy that type, not because the fallback branch is ever
 * expected to run.
 */

export interface ScriptTag {
  attrs: string;
  body: string;
  src: string | null;
  type: string | null;
}

export function extractScripts(html: string): ScriptTag[] {
  const out: ScriptTag[] = [];
  for (const m of html.matchAll(/<script([^>]*)>([\s\S]*?)<\/script>/gi)) {
    const attrs = m[1] ?? '';
    const body = m[2] ?? '';
    out.push({
      attrs,
      body,
      src: attrValue(attrs, 'src'),
      type: attrValue(attrs, 'type'),
    });
  }
  return out;
}

export const NON_EXECUTABLE_SCRIPT_TYPES = new Set([
  'application/json',
  'application/ld+json',
  'importmap',
  'speculationrules',
  'text/template',
]);

/** Scripts with a body that the browser would actually execute — not JSON data islands. */
export function executableInlineScripts(html: string): ScriptTag[] {
  return extractScripts(html).filter(
    (s) => !s.src && s.body.trim() && !NON_EXECUTABLE_SCRIPT_TYPES.has(s.type ?? ''),
  );
}

export function attrValue(attrs: string, name: string): string | null {
  const m = attrs.match(new RegExp(`${name}\\s*=\\s*"([^"]*)"`, 'i'));
  return m ? (m[1] ?? '') : null;
}

export interface StyleTag {
  attrs: string;
  body: string;
}

export function extractInlineStyles(html: string): StyleTag[] {
  return [...html.matchAll(/<style([^>]*)>([\s\S]*?)<\/style>/gi)].map((m) => ({
    attrs: m[1] ?? '',
    body: m[2] ?? '',
  }));
}

/** `<link rel="stylesheet" href="...">` hrefs — external stylesheets only. */
export function extractStylesheetHrefs(html: string): string[] {
  return [...html.matchAll(/<link[^>]+rel="stylesheet"[^>]+href="([^"]+)"/gi)].map(
    (m) => m[1] ?? '',
  );
}

/** `<script src="...">` — external scripts only. */
export function extractScriptSrcs(html: string): string[] {
  return [...html.matchAll(/<script[^>]+src="([^"]+)"/gi)].map((m) => m[1] ?? '');
}

export interface CanonicalHreflang {
  canonical: string | null;
  hreflang: Map<string, string>;
  noindex: boolean;
}

/** A page's canonical tag, full hreflang alternate set, and noindex status. */
export function extractSeoMeta(html: string): CanonicalHreflang {
  const canonicals = [...html.matchAll(/<link rel="canonical" href="([^"]+)"/g)];
  const hreflang = new Map<string, string>();
  for (const m of html.matchAll(/<link rel="alternate" hreflang="([^"]+)" href="([^"]+)"/g)) {
    const lang = m[1];
    const href = m[2];
    if (lang && href) hreflang.set(lang, href);
  }
  return {
    canonical: canonicals[0]?.[1] ?? null,
    hreflang,
    noindex: /<meta name="robots" content="[^"]*noindex/i.test(html),
  };
}

export interface FetchingResource {
  tag: string;
  url: string;
}

/**
 * Every URL the browser actually FETCHES from tags in this HTML: script/link
 * (stylesheet|icon|preload|modulepreload only — other rels like canonical or
 * alternate don't trigger a request)/img/source/iframe. Deliberately excludes
 * plain `<a href>` outbound links, which are not requests the page makes on
 * load.
 */
export function extractFetchedResources(html: string): FetchingResource[] {
  const out: FetchingResource[] = [];
  for (const tagMatch of html.matchAll(/<(script|link|img|source|iframe)\b([^>]*)>/gi)) {
    const tag = tagMatch[1] ?? '';
    const attrs = tagMatch[2] ?? '';
    if (
      tag.toLowerCase() === 'link' &&
      !/rel="(stylesheet|icon|preload|modulepreload)"/i.test(attrs)
    )
      continue;
    for (const urlMatch of attrs.matchAll(/(?:src|href|srcset)="([^"]+)"/gi)) {
      const raw = (urlMatch[1] ?? '').split(',')[0]?.trim().split(' ')[0] ?? ''; // first URL in a srcset
      out.push({ tag, url: raw });
    }
  }
  return out;
}

export interface AnchorLink {
  href: string;
}

/** Every `<a href="...">` in the document, href verbatim (not resolved). */
export function extractAnchorHrefs(html: string): string[] {
  return [...html.matchAll(/<a\b[^>]*\bhref="([^"]+)"/gi)].map((m) => m[1] ?? '');
}

/** Every element `id="..."` in the document — for anchor-target validation. */
export function extractElementIds(html: string): Set<string> {
  const ids = new Set<string>();
  for (const m of html.matchAll(/\bid="([^"]+)"/g)) {
    const id = m[1];
    if (id) ids.add(id);
  }
  return ids;
}

/**
 * `url`/`item` values from `<script type="application/ld+json">` blocks.
 * JSON-LD is escaped by `safeJsonLd()` (see src/lib/utils/safe-json-ld.ts) —
 * unescape enough (`<` etc.) to read the values back out without a full
 * JSON.parse, which would need to handle every possible schema.org shape.
 */
export function extractJsonLdUrls(html: string): string[] {
  const out: string[] = [];
  for (const m of html.matchAll(/<script[^>]+application\/ld\+json[^>]*>([\s\S]*?)<\/script>/gi)) {
    const raw = (m[1] ?? '')
      .replace(/\\u003c/g, '<')
      .replace(/\\u003e/g, '>')
      .replace(/\\u0026/g, '&');
    for (const um of raw.matchAll(/"(?:url|item)":"([^"]+)"/g)) {
      const url = um[1];
      if (url) out.push(url);
    }
  }
  return out;
}
